// static
bool StructTraits<::webnn::mojom::CreateTensorSuccess::DataView, ::webnn::mojom::CreateTensorSuccessPtr>::Read(
    ::webnn::mojom::CreateTensorSuccess::DataView input,
    ::webnn::mojom::CreateTensorSuccessPtr* output) {
  bool success = true;
  ::webnn::mojom::CreateTensorSuccessPtr result(::webnn::mojom::CreateTensorSuccess::New());
  
      if (success) {
        result->tensor_remote =
            input.TakeTensorRemote<decltype(result->tensor_remote)>();
      }
      if (success && !input.ReadTensorHandle(&result->tensor_handle))
        success = false;
  *output = std::move(result);
  return success;
}

// static
bool UnionTraits<::webnn::mojom::CreateTensorResult::DataView, ::webnn::mojom::CreateTensorResultPtr>::Read(
    ::webnn::mojom::CreateTensorResult::DataView input,
    ::webnn::mojom::CreateTensorResultPtr* output) {
  using UnionType = ::webnn::mojom::CreateTensorResult;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kSuccess: {
      ::webnn::mojom::CreateTensorSuccessPtr result_success{};
      if (!input.ReadSuccess(&result_success))
        return false;

      *output = UnionType::NewSuccess(
          std::move(result_success));
      break;
    }
    case Tag::kError: {
      ::webnn::mojom::ErrorPtr result_error{};
      if (!input.ReadError(&result_error))
        return false;

      *output = UnionType::NewError(
          std::move(result_error));
      break;
    }
    default:

      return false;
  }
  return true;
}

