WebNNContextAsyncWaiter::WebNNContextAsyncWaiter(
    WebNNContext* proxy) : proxy_(proxy) {}

WebNNContextAsyncWaiter::~WebNNContextAsyncWaiter() = default;


void WebNNContextAsyncWaiter::CreateTensor(
    ::webnn::mojom::TensorInfoPtr tensor_info, CreateTensorResultPtr* out_result) {
  base::RunLoop loop;
  proxy_->CreateTensor(
      std::move(tensor_info),
      base::BindOnce(
          [](base::RunLoop* loop,
             CreateTensorResultPtr* out_result
,
             CreateTensorResultPtr result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

CreateTensorResultPtr WebNNContextAsyncWaiter::CreateTensor(
    ::webnn::mojom::TensorInfoPtr tensor_info) {
  CreateTensorResultPtr async_wait_result;
  CreateTensor(std::move(tensor_info),&async_wait_result);
  return async_wait_result;
}

void WebNNContextAsyncWaiter::CreateTensorFromMailbox(
    ::webnn::mojom::TensorInfoPtr tensor_info, const ::gpu::Mailbox& mailbox, const std::vector<::gpu::SyncToken>& fences, CreateTensorResultPtr* out_result) {
  base::RunLoop loop;
  proxy_->CreateTensorFromMailbox(
      std::move(tensor_info),
      std::move(mailbox),
      std::move(fences),
      base::BindOnce(
          [](base::RunLoop* loop,
             CreateTensorResultPtr* out_result
,
             CreateTensorResultPtr result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

CreateTensorResultPtr WebNNContextAsyncWaiter::CreateTensorFromMailbox(
    ::webnn::mojom::TensorInfoPtr tensor_info, const ::gpu::Mailbox& mailbox, const std::vector<::gpu::SyncToken>& fences) {
  CreateTensorResultPtr async_wait_result;
  CreateTensorFromMailbox(std::move(tensor_info),std::move(mailbox),std::move(fences),&async_wait_result);
  return async_wait_result;
}






